cd /home/user/deepseek-harness; node -e '
const fs=require("fs");
function resolve(path, mine, theirsAnchor){
  let text=fs.readFileSync(path,"utf8");
  // hunk 1: layout block — keep both lines, datasets first then dashboard
  text=text.replace(/<<<<<<< HEAD\n(  dashboard\.html[^\n]*\n)=======\n(  datasets\/<name>\/[^\n]*\n)>>>>>>> [^\n]*\n/, (m,a,b)=>b+a);
  // hunk 2: tools paragraph — take theirs and insert my sentence before their build-dataset sentence
  text=text.replace(/<<<<<<< HEAD\n([^\n]*)\n=======\n([^\n]*)\n>>>>>>> [^\n]*\n/, (m,head,theirs)=>{
    const start=head.indexOf(mine.start); const end=head.indexOf(mine.end,start)+mine.end.length;
    if(start<0||end<mine.end.length) throw new Error("my sentence not found in HEAD paragraph of "+path);
    const sentence=head.slice(start,end);
    const at=theirs.indexOf(theirsAnchor); if(at<0) throw new Error("anchor not found in theirs for "+path);
    return theirs.slice(0,at)+sentence+" "+theirs.slice(at)+"\n";
  });
  if(/^(<<<<<<<|=======|>>>>>>>)/m.test(text)) throw new Error("conflict markers remain in "+path);
  fs.writeFileSync(path,text);
}
resolve("data/proving-ground/README.md", {start:"[`tools/build-dashboard.mjs`]", end:"still writing."}, "[`tools/build-dataset.mjs`]");
resolve("data/proving-ground/README.zh.md", {start:"[`tools/build-dashboard.mjs`]", end:"仍在写入的运行。"}, "[`tools/build-dataset.mjs`]");
console.log("resolved");
'; git checkout --theirs data/proving-ground/README.i18n.yaml 2>/dev/null; grep -c "^<<<<<<<\|^>>>>>>>" data/proving-ground/README.md data/proving-ground/README.zh.md; sed -n 21,23p data/proving-ground/README.md | cut -c1-80; grep -o "read from it\. \[\`tools/build-dashboard.mjs\`\][^.]*\.[^.]*\.[^.]*\. \[\`tools/build-dataset.mjs\`\]" data/proving-ground/README.md | cut -c1-80; timeout 300 pnpm run -s verify-translation-pairing --write data/proving-ground/README.md 2>&1 | tail -1; git add data/proving-ground/README.md data/proving-ground/README.zh.md data/proving-ground/README.i18n.yaml; git diff --cached --check; timeout 300 pnpm exec tsx scripts/verify-translation-pairing.ts 2>&1 | tail -1; timeout 300 pnpm exec tsx scripts/verify-md-links.ts 2>&1 | tail -1; git -c core.hooksPath=/dev/null commit -q -m "merge: the Proving Ground dataset fold (build-dataset.mjs, datasets/2026-09-18-proving-ground-v1 manifest and README)" -m "Co-Authored-By: Claude Fable 5.1 <noreply@anthropic.com>" -m "Claude-Session: https://claude.ai/code/session_01HEXjzxR7CyMizem5kFAB4C" && git log --oneline -1; node data/proving-ground/tools/build-dataset.mjs 2026-09-18-proving-ground-v1 --check 2>&1 | tail -2; date -u +%T

