+.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:var(--radius);background:var(--surface)}
+table.records{border-collapse:collapse;width:100%;font-size:.82rem;min-width:70rem}
+table.records th,table.records td{padding:.45rem .55rem;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
+table.records th{position:sticky;top:0;background:var(--surface-2);font-weight:600;white-space:nowrap;cursor:pointer;user-select:none}
+table.records th[aria-sort="ascending"]::after{content:" \25B4"}table.records th[aria-sort="descending"]::after{content:" \25BE"}
