+    $('record-controls').querySelectorAll('button[data-kind]').forEach(b => b.addEventListener('click', () => { kindFilter = b.dataset.kind || null; renderRecords() }))
+    $('record-controls').querySelectorAll('button[data-tier]').forEach(b => b.addEventListener('click', () => { tierFilter = b.dataset.tier ? Number(b.dataset.tier) : null; renderRecords() }))
+    renderTable()
+  }
+  function renderTable() {
+    const rows = allRecords.filter(r => (!kindFilter || r.kind === kindFilter) && (!tierFilter || r.tiers.includes(tierFilter)) && (!query || r.search.includes(query)))
+      .sort((a, b) => { const x = a[sortKey], y = b[sortKey]; const c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x ?? '').localeCompare(String(y ?? '')); return c * sortDir })
+    $('records').innerHTML = `<thead><tr>${columns.map(([k, l, t]) => `<th class="${t}" data-key="${k}" aria-sort="${sortKey === k ? (sortDir > 0 ? 'ascending' : 'descending') : 'none'}">${l}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr class="record" data-name="${esc(r.name)}" tabindex="0">${columns.map(([k, , t, f]) => `<td class="${t}">${f(r)}</td>`).join('')}</tr>`).join('')}</tbody>`
+    $('records').querySelectorAll('th').forEach(th => th.addEventListener('click', () => { const k = th.dataset.key; if (sortKey === k) sortDir = -sortDir; else { sortKey = k; sortDir = k === 'ranAt' || k === 'name' ? -1 : -1 } renderTable() }))
+    $('records').querySelectorAll('tr.record').forEach(tr => {
+      const open = () => {
+        const next = tr.nextElementSibling
+        if (next && next.classList.contains('detail')) { next.remove(); tr.classList.remove('open'); return }
+        const r = allRecords.find(x => x.name === tr.dataset.name)
+        const d = document.createElement('tr'); d.className = 'detail'; d.innerHTML = `<td colspan="${columns.length}">${detail(r)}</td>`
+        tr.after(d); tr.classList.add('open')
+      }
+      tr.addEventListener('click', (e) => { if (e.target.closest('a')) return; open() })
+      tr.addEventListener('keydown', (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open() } })
+    })
+  }
+  renderRecords()
+
+  // ---- routing + repeatability
+  if (D.readings.routing) {
+    const rs = D.readings.routing.results
+    const max = Math.max(...rs.map(r => r.output))
+    $('routing').innerHTML = `<table class="plain"><thead><tr><th>router</th><th class="num">certified</th><th class="num">output tokens</th><th class="num">steps</th><th class="num">cell time</th></tr></thead><tbody>${rs.map(r => `<tr><td>${esc(r.router)}</td><td class="num">${r.certified}/${r.cells}</td><td class="num"><div class="bar-track" style="display:inline-block;width:7rem;vertical-align:middle;margin-right:.4rem"><div class="bar-fill" style="width:${(r.output / max) * 100}%;background:var(--accent)"></div></div>${fmt(r.output)}</td><td class="num">${fmt(r.steps)}</td><td class="num">${secs(r.secs)}</td></tr>`).join('')}</tbody></table><p style="color:var(--muted);font-size:.8rem;margin:.6rem 0 0">${esc(D.readings.routing.note)}</p>`
+  }
+  if (D.readings.repeatability) {
+    const rp = D.readings.repeatability
+    $('repeatability').innerHTML = `<table class="plain"><thead><tr><th>arms compared</th><th class="num">both</th><th class="num">neither</th><th class="num">flips</th><th class="num">flip rate</th></tr></thead><tbody>${rp.pairs.map(p => `<tr><td>${esc(p.a)} · ${esc(p.b)}</td><td class="num">${p.both}</td><td class="num">${p.neither}</td><td class="num">${p.flips}</td><td class="num">${(p.flipRate * 100).toFixed(1)} %</td></tr>`).join('')}</tbody></table><p style="color:var(--muted);font-size:.8rem;margin:.6rem 0 0">${esc(rp.note)}</p>`
+  }
+
+  // ---- notes + footer
+  $('notes').innerHTML = D.notes.map(n => `<p>${n}</p>`).join('')
+  $('footer').innerHTML = `Built by <span class="mono">data/proving-ground/tools/build-dashboard.mjs</span> at ${esc(when(D.builtAt))} from ${D.summary.records} records on <span class="mono">${esc(D.branch)}</span> @ <span class="mono">${esc(D.head.slice(0, 9))}</span>. Records: <a href="${esc(D.linkBase)}data/proving-ground/README.md">README</a> · results: <a href="${esc(D.linkBase)}.agents/notes/proposed/architecture/2026-09-08-hypothesis-program-results.md">hypothesis program</a>.`
+})()
+</script>

