  }
  const rewardColor = (r) => r.label === '1' ? 'var(--good)' : r.label === '0' ? 'var(--critical)' : 'var(--neutral)'
  const modelColor = (r) => SERIES[D.routeSlots[String(r.label).split('/').pop()] ?? 3]
  $('dataset').innerHTML = `<div>
      <div class="stats" style="border:none;padding-block:0 .75rem">${[[c.train, 'trajectories in train'], [c.seen, 'seen'], [c.delegatedExcluded, 'delegated, excluded'], [c.duplicatesDropped, 'duplicates dropped'], [c.tamperedExcluded, 'tampered, excluded'], [c.withheldHeldOut, 'held out, withheld']].map(([n, l]) => `<div class="stat"><b>${fmt(n)}</b><span>${l}</span></div>`).join('')}</div>
      ${distBars('reward', dist.reward, rewardColor)}
      <p class="arms" style="margin:.75rem 0 0;color:var(--muted);font-size:.8rem">Tokens over the training steps: ${fmt(ds.tokens?.outputTokens)} output, ${fmt(ds.tokens?.cacheReadTokens)} cache-read, ${fmt(ds.tokens?.cacheWriteTokens)} cache-write, over ${fmt(ds.tokens?.stepsWithUsage)} of ${fmt(ds.tokens?.steps)} steps. Files: ${(ds.files ?? []).map(f => `${esc(f.path)} (${fmt(f.bytes)} bytes)`).join(', ')}.</p>
    </div>
    <div class="bars" style="gap:1rem">${distBars('model route', dist.model, modelColor)}${distBars('tier', dist.tier, () => 'var(--accent)')}${distBars('arm', dist.arm, () => 'var(--accent)')}</div>`
}

// ---- notes + footer

