// Offline fold of an experiment run whose driver died before folding: rebuilds
// each arm's fleet report from the cell session logs the run left behind and
// computes the same paired delta, bootstrap interval, and verdict the
// experiments service computes, labelled offline.
//
//   tsx sessions-fold.ts <run dir> <out.json> <baseline label> <candidate label>
import { createHash } from 'node:crypto'
import { readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { foldExperiment } from '/home/user/deepseek-harness/packages/improvement/experiments/src/index.ts'
import { summarizeRun } from '/home/user/deepseek-harness/data/proving-ground/tools/summarize-run.mjs'

const [runDir, outPath, baselineLabel, candidateLabel] = process.argv.slice(2)
if (!runDir || !outPath || !baselineLabel || !candidateLabel) throw new Error('usage: sessions-fold.ts <run dir> <out.json> <baseline label> <candidate label>')

const plan = JSON.parse(await readFile(join(runDir, 'plan.json'), 'utf8'))
const summary = summarizeRun(runDir) as { rows: any[] }
const rows = summary.rows
const environments = [...new Set(rows.map(row => row.environment as string))].sort()
const repetitions = Math.max(...rows.map(row => row.repetition as number)) + 1

function reportOf(arm: 'baseline' | 'candidate') {
  const model = { provider: plan[arm].provider, model: plan[arm].model }
  return {
    cells: rows.filter(row => row.arm === arm).map(row => ({
      cell: { environment: row.environment, repetition: row.repetition, model },
      report: {
        certified: row.certified,
        attempts: new Array(row.attempts).fill({}),
        usage: { inputTokens: row.inputTokens, outputTokens: row.outputTokens },
      },
    })),
  }
}

const digest = createHash('sha256')
  .update(JSON.stringify({ offline: 1, baseline: baselineLabel, candidate: candidateLabel, environments, repetitions }))
  .digest('hex')
const thresholds = { bootstrapResamples: 2000, confidenceLevel: 0.95, minimumDelta: 0.05, cellTokenCap: 600000 }
const armOf = (arm: 'baseline' | 'candidate') => ({
  model: { provider: plan[arm].provider, model: plan[arm].model },
  ...plan[arm].ladder === undefined ? {} : { ladder: plan[arm].ladder },
  implementer: plan[arm].implementer ?? { kind: 'route' },
  group: `offline-${digest}-${arm}`,
})
const result = foldExperiment({
  digest,
  arms: { baseline: armOf('baseline'), candidate: armOf('candidate') },
  environments: environments as any,
  repetitions,
  thresholds,
  caps: [],
  baseline: reportOf('baseline') as any,
  candidate: reportOf('candidate') as any,
})
const cellsRan = { baseline: rows.filter(row => row.arm === 'baseline').length, candidate: rows.filter(row => row.arm === 'candidate').length }
const record = {
  type: 'offline-fold',
  baseline: baselineLabel,
  candidate: candidateLabel,
  plan: plan.name,
  environments,
  repetitions,
  cellsRan,
  cellsPlanned: environments.length * repetitions,
  thresholds,
  result,
}
await writeFile(outPath, `${JSON.stringify(record, null, 2)}\n`)
process.stdout.write(`${JSON.stringify({ type: 'offline-fold', plan: plan.name, cellsRan, seedsPaired: result.seedsPaired, delta: result.delta, interval: result.interval, verdict: result.verdict })}\n`)

