+  const fmt = (n) => n === undefined || n === null || Number.isNaN(n) ? '–' : Number(n).toLocaleString('en-US')
+  const secs = (s) => s === undefined || s === null ? '–' : s < 3600 ? `${Math.round(s / 60)} min` : `${(s / 3600).toFixed(1)} h`
