+    + `<div class="stat"><b class="mono" style="font-size:1rem">${esc(D.head.slice(0, 9))}</b><span>head · built ${esc(when(D.builtAt))}</span></div>`
+
+  // ---- interval bar (SVG): axis -1..1 clipped to the widest interval, 0 line, minimum-delta tick
