+    parts.push(`<text x="${pad}" y="35" text-anchor="start">${(-span).toFixed(2)}</text><text x="${x(0)}" y="35" text-anchor="middle">0</text><text x="${W - pad}" y="35" text-anchor="end">+${span.toFixed(2)}</text>`)
