+  }
+
+  // ---- verdict cards
+  const verdictLabel = { promote: 'promote', reject: 'reject', inconclusive: 'inconclusive', running: 'running' }
+  function verdictCard(e) {
+    const v = e.verdict ?? 'running'
+    const count = (arm) => arm && arm.cells ? `<span class="num">${arm.certified} <small>of ${arm.cells}</small></span>` : '<span class="num">–</span>no cell ran'
