+    return `<article class="verdict" data-verdict="${v}" data-method="${esc(e.method)}">
+      <div class="top"><div><div class="name">${esc(e.label)}</div><div class="arms"><b>${esc(e.baselineLabel)}</b> vs <b>${esc(e.candidateLabel)}</b></div></div><span class="pill ${v}">${verdictLabel[v]}</span></div>
