+      ${counts}
+      <div class="interval">${e.delta === undefined ? '' : intervalSvg(e.delta, e.interval, e.minimumDelta)}<div class="arms">Δ ${e.delta === undefined ? '–' : signed(e.delta)}${e.interval ? ` [${signed(e.interval.lower)}, ${signed(e.interval.upper)}]` : ''} · <a href="${esc(e.href)}">${esc(e.source)}</a></div></div>
+    </article>`
+  }
+  const order = { promote: 0, reject: 1, inconclusive: 2 }
+  const exps = [...D.experiments].sort((a, b) => (order[a.verdict] - order[b.verdict]) || a.date.localeCompare(b.date))
