+  }
+  renderVerdicts()
+
+  // ---- live
+  if (D.live.length) {
+    $('live-section').hidden = false
+    $('live').innerHTML = D.live.map(l => `<article class="verdict" data-verdict="running">
+      <div class="top"><div><div class="name">${esc(l.label)}</div><div class="arms">${esc(l.description)}</div></div><span class="pill running pulse">running</span></div>
