+      + `<div class="legend" style="margin-top:.6rem">${rated.map(m => `<span><i style="background:${colorOf(m)}"></i>${esc(m.label)} · ${pct(m.certified, m.cells)} % certified, ${m.firstAttempt} at the first attempt, over ${m.runs} run${m.runs === 1 ? '' : 's'}</span>`).join('')}</div>`
+    $('cost').innerHTML = barChart(rated, 'outputPerCertified', Math.max(...rated.map(m => m.outputPerCertified || 0)), colorOf, r => r.outputPerCertified ? fmt(Math.round(r.outputPerCertified)) : '–')
+      + `<div class="legend" style="margin-top:.6rem">${rated.map(m => `<span><i style="background:${colorOf(m)}"></i>${esc(m.label)} · ${fmt(m.output)} output tokens over ${m.cells} cells · median cell ${secs(m.secondsMedian)}</span>`).join('')}</div>`
