*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.5 "IBM Plex Sans",ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;padding-block:0 4rem;padding-inline:clamp(16px,3vw,40px)}
a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}
:focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.mono,.num,td.num,th.num,.cell-grid,.rows td,.rows th{font-family:"IBM Plex Mono",ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-variant-numeric:tabular-nums}
h1{font:600 clamp(2rem,4vw,2.75rem)/1.05 Fraunces,Georgia,"Times New Roman",serif;letter-spacing:-0.01em;margin:0;text-wrap:balance}
h2{font:600 1.05rem/1.3 "IBM Plex Sans",system-ui,sans-serif;margin:0 0 .75rem;letter-spacing:.01em}
h3{font:500 .95rem/1.3 "IBM Plex Sans",system-ui,sans-serif;margin:0 0 .5rem}
.eyebrow{font-size:.72rem;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);font-weight:500}
header{max-width:80rem;margin:0 auto;padding-block:2.25rem 1.5rem;display:grid;gap:1rem}
header p.lede{max-width:64ch;margin:0;color:var(--muted);font-size:1rem}
.stats{display:flex;flex-wrap:wrap;gap:.5rem 2rem;padding-block:.75rem;border-block:1px solid var(--line)}
.stat b{display:block;font:500 1.35rem/1.1 "IBM Plex Mono",monospace;font-variant-numeric:tabular-nums}
.stat span{font-size:.78rem;color:var(--muted)}
main{max-width:80rem;margin:0 auto;display:grid;gap:2.25rem}
section{display:grid;gap:.75rem}
.section-head{display:flex;flex-wrap:wrap;align-items:baseline;gap:.5rem 1.25rem}
.section-head p{margin:0;color:var(--muted);max-width:70ch}
.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:1rem}
.two{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:1.25rem}
@media (max-width:900px){.two{grid-template-columns:minmax(0,1fr)}}
/* verdict strip */
.verdicts{display:grid;grid-template-columns:repeat(auto-fill,minmax(19rem,1fr));gap:.75rem}
.verdict{display:grid;grid-template-rows:auto auto 1fr auto;gap:.5rem;background:var(--surface);border:1px solid var(--line);border-radius:var(--radius);padding:.85rem .95rem;border-left-width:4px}
.verdict[data-verdict="promote"]{border-left-color:var(--good)}
.verdict[data-verdict="reject"]{border-left-color:var(--critical)}
.verdict[data-verdict="inconclusive"]{border-left-color:var(--neutral)}
.verdict[data-verdict="running"]{border-left-color:var(--running)}
.verdict .top{display:flex;justify-content:space-between;gap:.5rem;align-items:flex-start}
.verdict .name{font-weight:600}
.verdict .arms{color:var(--muted);font-size:.82rem;line-height:1.4}
.verdict .arms b{color:var(--ink);font-weight:500}
.verdict .counts{display:grid;grid-template-columns:1fr 1fr;gap:.5rem;font-size:.82rem}
.verdict .counts .num{font-size:1.15rem;font-weight:500;display:block}
.pill{display:inline-flex;align-items:center;gap:.35rem;font-size:.72rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;padding:.15rem .5rem;border-radius:999px;border:1px solid var(--line-strong);color:var(--ink);white-space:nowrap}
.pill::before{content:"";width:.5rem;height:.5rem;border-radius:50%;background:var(--neutral)}
.pill.promote::before{background:var(--good)}.pill.reject::before{background:var(--critical)}.pill.running::before{background:var(--running)}
.tag{display:inline-block;font-size:.7rem;color:var(--muted);border:1px solid var(--line);border-radius:3px;padding:0 .35rem;letter-spacing:.04em}
.interval svg{width:100%;height:38px;display:block}
.interval text{font-family:"IBM Plex Mono",monospace;font-size:10px;fill:var(--muted)}
/* charts */
.bars{display:grid;gap:.45rem}
