// Print the README table rows (EN and ZH) for a two-arm experiment record in the Runs table's format.
//   node rows.mjs <record dir> <name> <head> "<en implementer column>" "<zh implementer column>"
import { summarizeRun } from '/home/user/deepseek-harness/data/proving-ground/tools/summarize-run.mjs'

const [dir, name, head, en, zh] = process.argv.slice(2)
const { rows } = summarizeRun(dir)
const envs = [...new Set(rows.map(r => r.environment))].sort()
const fmt = n => n.toLocaleString('en-US')
const attemptsEn = list => (list.length === 2 && list[0] === list[1]) ? `${list[0]} each` : list.join(' and ')
const attemptsZh = list => (list.length === 2 && list[0] === list[1]) ? `各 ${list[0]}` : list.join(' 与 ')
const secsEn = list => `${list.map(fmt).join(', ')} s`
const secsZh = list => `${list.map(fmt).join('、')} s`
for (const env of envs) {
  const arm = a => rows.filter(r => r.arm === a && r.environment === env).sort((x, y) => x.repetition - y.repetition)
  const b = arm('baseline'), c = arm('candidate')
  const cert = list => `${list.filter(r => r.certified).length} of ${list.length}`
  const certZh = list => `${list.filter(r => r.certified).length} 之 ${list.length}`
  console.log(`| [${name}](${name}/manifest.json) | \`${head}\` | ${en} | \`${env}\` | ${cert(b)} vs ${cert(c)} | ${attemptsEn(b.map(r => r.attempts))} vs ${attemptsEn(c.map(r => r.attempts))} | ${secsEn(b.map(r => r.seconds))} vs ${secsEn(c.map(r => r.seconds))} |`)
  console.error(`| [${name}](${name}/manifest.json) | \`${head}\` | ${zh} | \`${env}\` | ${certZh(b)} 对 ${certZh(c)} | ${attemptsZh(b.map(r => r.attempts))} 对 ${attemptsZh(c.map(r => r.attempts))} | ${secsZh(b.map(r => r.seconds))} 对 ${secsZh(c.map(r => r.seconds))} |`)
}

